// Check the actual production HTML before deployment: optimizers must preserve
// the blog cards generated by builders/BlogBuilder.js and the homepage journal.
const fs = require('fs');
const path = require('path');
const assert = require('assert/strict');
const { parser } = require('posthtml-parser');
const { decodeHTML } = require('entities');
const { publicationMetadata } = require('./article-publication');
const { halloweenCardCover } = require('./halloween-card-cover');
const root = path.resolve(__dirname, '..');
const flatten = nodes => nodes.flatMap(node => typeof node === 'object' ? [node, ...flatten(node.content || [])] : []);
const hasClass = (node, name) => (node.attrs?.class || '').split(/\s+/).includes(name);
const text = node => decodeHTML((node.content || []).map(child => typeof child === 'string' ? child : text(child)).join('')).trim();
const cardsOf = file => flatten(parser(fs.readFileSync(path.join(root, file), 'utf8'))).filter(node => hasClass(node, 'blog-card'));
const cardData = card => {
  const children = flatten(card.content || []);
  const image = children.find(node => node.tag === 'img');
  const time = children.find(node => node.tag === 'time');
  const badge = children.find(node => hasClass(node, 'blog-card-category'));
  const title = children.find(node => hasClass(node, 'blog-card-title'));
  const excerpt = children.find(node => hasClass(node, 'blog-card-excerpt'));
  return {
    href: card.attrs?.href,
    category: card.attrs?.['data-category'],
    image: image?.attrs?.src,
    width: Number(image?.attrs?.width),
    height: Number(image?.attrs?.height),
    alt: decodeHTML(image?.attrs?.alt ?? ''),
    date: time?.attrs?.datetime,
    dateText: text(time),
    categoryLabel: text(badge),
    title: text(title),
    excerpt: text(excerpt)
  };
};
let count = 0;
for (const directory of ['en', 'es', 'ja', 'zh-Hant', 'de', 'pt', 'fr']) {
  const blogSource = cardsOf(`${directory}/blog.html`);
  const blogDeployed = cardsOf(`dist/${directory}/blog.html`);
  assert(blogSource.length > 0, `${directory}/blog.html: missing source cards`);
  assert.equal(blogDeployed.length, blogSource.length, `${directory}/blog.html: card count`);
  for (const [index, card] of blogSource.entries()) {
    const expected = cardData(card);
    const actual = cardData(blogDeployed[index]);
    assert.deepEqual(actual, expected, `${directory}/blog.html: preserved card ${index} (${expected.href})`);
    const publication = publicationMetadata(path.join(root, directory, expected.href), directory);
    assert.equal(expected.date, publication.date, `${directory}/blog.html: publication date for ${expected.href}`);
    assert.equal(expected.dateText, publication.dateText, `${directory}/blog.html: publication text for ${expected.href}`);
    if (expected.category === 'halloween-gifts') {
      const cover = halloweenCardCover(directory, expected.href);
      assert.equal(expected.image, cover.image, `${directory}/blog.html: Halloween cover`);
      assert.equal(expected.width, cover.width, `${directory}/blog.html: Halloween width`);
      assert.equal(expected.height, cover.height, `${directory}/blog.html: Halloween height`);
      assert.equal(expected.alt, cover.alt, `${directory}/blog.html: Halloween alt`);
    }
    count++;
  }

  const indexSource = fs.readFileSync(path.join(root, directory, 'index.html'), 'utf8');
  const expectedIndex = [...indexSource.matchAll(/<include src="components\/blog-card\.html">([\s\S]*?)<\/include>/g)].map(match => JSON.parse(match[1]));
  const indexDeployed = cardsOf(`dist/${directory}/index.html`);
  assert.equal(indexDeployed.length, expectedIndex.length, `${directory}/index.html: card count`);
  for (const [index, post] of expectedIndex.entries()) {
    const actual = cardData(indexDeployed[index]);
    const publication = publicationMetadata(path.join(root, directory, post.href), directory);
    assert.equal(post.date, publication.date, `${directory}/index.html: source date for ${post.href}`);
    assert.equal(post.dateText, publication.dateText, `${directory}/index.html: source date text for ${post.href}`);
    assert.equal(actual.href, post.href, `${directory}/index.html: article link`);
    assert.equal(actual.category, post.category, `${directory}/index.html: category`);
    assert.equal(actual.categoryLabel, post.categoryLabel, `${directory}/index.html: category text`);
    assert.equal(actual.date, post.date, `${directory}/index.html: publication date`);
    assert.equal(actual.dateText, post.dateText, `${directory}/index.html: visible date text`);
    assert.equal(actual.image, post.image, `${directory}/index.html: production cover`);
    count++;
  }
}
console.log(`Verified ${count} blog cards in source and production HTML.`);
